def canonicalize_args(args: dict[str, Any]) -> str:
    # Sort keys in args recursively
    sorted_args = {k: canonicalize_args(v) if isinstance(v, dict) else v for k, v in sorted(args.items())}
    # Convert tuples to lists
    converted_args = {k: list(v) if isinstance(v, tuple) else v for k, v in sorted_args.items()}
    # Ensure numeric and boolean values remain as proper Python types
    cleaned_args = {k: (int(v) if isinstance(v, (int, float)) else v) for k, v in converted_args.items()}
    # Strip leading/trailing whitespace from string values
    trimmed_args = {k: v.strip() if isinstance(v, str) else v for k, v in cleaned_args.items()}
    # Serialize the canonicalized object with json.dumps
    canonicalized_str = json.dumps(trimmed_args, sort_keys=True, separators=(',', ':'))
    return canonicalized_str

